    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new Xxd47Exception("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new Xrf10Exception("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }




    private Xzj27 createAndSaveOrderBid(Xrd81 user, Xdh20 productSize, int bidPrice, Xdg64 order) {
        Xzj27 orderBid = Xzj27.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(Xtz73Status.PENDING)
                .order(order)
                .build();


        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }














    @Transactional
    public Xzj27 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
                                          boolean isWarehouseStorage, Xbf54RequestDto paymentRequest) {
        try {

            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);


            Xrd81 buyer = userQueryService.findByEmail(buyerEmail);


            Xzz58 saleBid = getSaleBidAndValidate(saleBidId);
            Xgg74 sale = saleBid.getSale();


            Xdg64 order = orderCommandService.createInstantOrder(
                    buyer,
                    saleBid,
                    addressId,
                    isWarehouseStorage,
                    paymentRequest
            );


            Xzj27 orderBid = createInstantOrderBid(order, saleBid, sale);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
            return null;
        }
    }




    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, Xbf54RequestDto paymentRequest) {
        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
            throw new Xxd47Exception("구매자 이메일이 없습니다.");
        }
        if (saleBidId == null) {
            throw new Xkt44Exception("판매 입찰 ID가 없습니다.");
        }
        if (addressId == null) {
            throw new Xnb95Exception("배송지 ID가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new Xtj87Exception("결제 정보가 없습니다.");
        }
    }




    private Xzz58 getSaleBidAndValidate(Long saleBidId) {
        Xzz58 saleBid = saleBidQueryService.findById(saleBidId);
        if (saleBid == null) {
            throw new Xkt44Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Xgg74 sale = saleBid.getSale();
        if (sale == null) {
            throw new Xnb95Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
